<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class MatchLineupEntry extends Model {protected $fillable=['football_match_id','team_id','player_id','player_name','shirt_number','position','x','y','is_starting','is_captain','rating']; protected function casts():array{return ['x'=>'float','y'=>'float','is_starting'=>'boolean','is_captain'=>'boolean','rating'=>'float'];} public function match(){return $this->belongsTo(FootballMatch::class,'football_match_id');} public function team(){return $this->belongsTo(Team::class);} public function player(){return $this->belongsTo(Player::class);}}
